const meta = {
  component: Empty,
  parameters: {
    docs: {
      description: {
        component: "## Usage

Use `Empty` for an absent item or an initial state. It includes a subtle dashed boundary and generous spacing by default. Place the icon, title, and description in `EmptyHeader`; place actions or inputs in `EmptyContent` as a sibling. Use `EmptyMedia` without a variant for larger artwork or avatars.

**Import:** `@/registry/erbium/ui/empty`

## Usage

```tsx
import { Icon } from "@/registry/erbium/ui/icon";
import { Button } from "@/registry/erbium/ui/button";
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
} from "@/registry/erbium/ui/empty";

<Empty>
  <EmptyHeader>
    <EmptyMedia variant="icon">
      <Icon name="folder-01" />
    </EmptyMedia>
    <EmptyTitle>No projects yet</EmptyTitle>
    <EmptyDescription>Create a project to get started.</EmptyDescription>
  </EmptyHeader>
  <EmptyContent>
    <Button>Create project</Button>
  </EmptyContent>
</Empty>;
```",
      },
    },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof Empty>;

export default { ...meta, title: "Components/Empty",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<{
  className: string;
  mediaVariant: "default" | "icon";
  title: string;
  description: string;
}> = {
  argTypes: {
    className: { control: "text" },
    description: { control: "text" },
    mediaVariant: { control: "select", options: ["default", "icon"] },
    title: { control: "text" },
  },
  args: PlaygroundDefaults,
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: "import { Icon } from "@/registry/erbium/ui/icon";
import {
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
