  mediaVariant: "icon",
  title: "No results",
} satisfies {
  className: string;
  mediaVariant: "default" | "icon";
  title: string;
  description: string;
};

export default function EmptyPlaygroundExample(
  args: {
    className: string;
    mediaVariant: "default" | "icon";
